int main(int argc, char** argv) {
    vbc_socket_system_init();
    vbc_stack_t _main_stack;
    vbc_stack_init(&_main_stack, (size_t)8192 * 1024 * 1024);

    vbc_slice_t _args = vbc_slice_create(&_main_stack, argc > 0 ? argc : 1, sizeof(vbc_string_t));
    for (int _ai = 0; _ai < argc; _ai++) {
        vbc_string_t _as = vbc_str_lit(argv[_ai]);
        vbc_slice_push(&_main_stack, &_args, &_as);
    }
    Vbc_Main(&_main_stack, _args);

    vbc_stack_free(&_main_stack);
    vbc_socket_system_cleanup();
    return 0;
}
